candidates.raw:
    adcs_vec3_t mapped_check_body;
    adcs_vec3_t n_mapped_check_body;
    adcs_vec3_t n_check_body;
    double dot;
    adcs_status_t status;

    if ((body_primary == NULL) || (body_secondary == NULL) ||
        (ref_primary == NULL) || (ref_secondary == NULL) ||
        (check_body == NULL) || (check_ref == NULL) ||
        (c_bi == NULL) || (alignment == NULL)) {
        return ADCS_E_NULL;
    }

    status = adcs_triad(body_primary, body_secondary, ref_primary, ref_secondary, c_bi);
    if (status != ADCS_OK) {
        *c_bi = adcs_mat3_identity();
        *alignment = 0.0;
        return status;
    }

    mapped_check_body = adcs_mat3_mul_vec(c_bi, check_ref);

    if (adcs_vec3_normalize(&mapped_check_body, ADCS_EPS_NORM, &n_mapped_check_body) != ADCS_OK) {
        return ADCS_E_DEGENERATE;
    }

    if (adcs_vec3_normalize(check_body, ADCS_EPS_NORM, &n_check_body) != ADCS_OK) {
        return ADCS_E_DEGENERATE;
    }

    dot = adcs_vec3_dot(&n_mapped_check_body, &n_check_body);
    *alignment = ADCS_CLAMP(dot, -1.0, 1.0);

    return ADCS_OK;
}

