    adcs_status_t status;
    adcs_vec3_t mapped_check_body;
    adcs_vec3_t norm_mapped_check_body;
    adcs_vec3_t norm_check_body;
    double alignment_val;

    /* 1. Null pointer check */
    if ((body_primary == NULL) || (body_secondary == NULL) ||
        (ref_primary == NULL) || (ref_secondary == NULL) ||
        (check_body == NULL) || (check_ref == NULL) ||
        (c_bi == NULL) || (alignment == NULL)) {
        return ADCS_E_NULL;
    }

    /* 2. TRIAD construction */
    status = adcs_triad(body_primary, body_secondary, ref_primary, ref_secondary, c_bi);
    if (status != ADCS_OK) {
        *c_bi = adcs_mat3_identity();
        *alignment = 0.0;
        return status;
    }

    /* 3. Map check_ref to body frame */
    mapped_check_body = adcs_mat3_mul_vec(c_bi, check_ref);

    /* 4. Normalize mapped_check_body */
    if (adcs_vec3_normalize(&mapped_check_body, ADCS_EPS_NORM, &norm_mapped_check_body) != ADCS_OK) {
        return ADCS_E_DEGENERATE;
    }

    /* 5. Normalize check_body */
    if (adcs_vec3_normalize(check_body, ADCS_EPS_NORM, &norm_check_body) != ADCS_OK) {
        return ADCS_E_DEGENERATE;
    }

    /* 6. Calculate alignment */
    alignment_val = adcs_vec3_dot(&norm_mapped_check_body, &norm_check_body);

    /* 7. Clamp alignment to [-1, 1] */
    if (alignment_val < -1.0) {
        alignment_val = -1.0;
    } else if (alignment_val > 1.0) {
        alignment_val = 1.0;
    }
    *alignment = alignment_val;

    return ADCS_OK;
}

